package net.officefloor.hq.app.rate;

/** The rate's grade is not one of A, B or C, or its percent is not 0.00 or more with up to two decimals, or its from- or to-date is not a date, or its to-date is before its from-date. */
public class InvalidRateException extends Exception {
    public InvalidRateException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated rate body: a grade of A, B or C, a percent of 0.00 or more and a from-date (null: from the start) and a to-date (null: without end). */
public record RateInput(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;

/**
 * A grade's rate on a sheet: a percent with two decimals, as the screen shows it, in force from its from-date
 * (yyyy-MM-dd; null when it applies from the beginning of time) through its to-date (null when it has no end).
 */
public record Rate(String grade, String pct, String from, String to) {

    /**
     * The percent the grade's rates give on a date: the one whose from-date is the latest on or before it, or null
     * when the date is before every rate the grade has, or after the to-date of that one.
     */
    public static String on(List<Rate> rates, String grade, LocalDate date) {
        return rates.stream().filter((r) -> r.grade().equals(grade))
                .filter((r) -> r.from() == null || !LocalDate.parse(r.from()).isAfter(date))
                .max(Comparator.comparing((Rate r) -> r.from() == null ? LocalDate.MIN : LocalDate.parse(r.from())))
                .filter((r) -> r.to() == null || !LocalDate.parse(r.to()).isBefore(date))
                .map(Rate::pct).orElse(null);
    }

    /** An amount times a percent, divided by 100, in hundredths rounded half to even; null when there is no rate. */
    public static BigDecimal due(String amount, String pct) {
        return due(amount, pct, RoundingMode.HALF_EVEN);
    }

    /**
     * An amount times a percent, divided by 100, in hundredths rounded by the mode (on the magnitude, so a negative
     * amount rounds as its positive would); null when there is no rate.
     */
    public static BigDecimal due(String amount, String pct, RoundingMode rounding) {
        return pct == null ? null
                : new BigDecimal(amount).multiply(new BigDecimal(pct)).movePointLeft(2).setScale(2, rounding);
    }
}
package net.officefloor.hq.app.rate;

/** Body of POST /api/sheets/{sheet}/rates; a blank from-date sets the rate that applies from the start, a blank to-date one without end. */
public record RateRequest(String grade, String pct, String from, String to) {
}
package net.officefloor.hq.app.rate;

import java.math.RoundingMode;
import java.sql.Date;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The rates kept per sheet: per grade, one for each from-date (and at most one with none). */
@Repository
public class Rates {

    private static final RowMapper<Rate> ROW = (rs, i) -> new Rate(rs.getString("grade"),
            rs.getBigDecimal("pct").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getDate("from_date") == null ? null : rs.getDate("from_date").toLocalDate().toString(),
            rs.getDate("to_date") == null ? null : rs.getDate("to_date").toLocalDate().toString());

    private final JdbcTemplate jdbc;

    public Rates(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every rate on the sheet, by grade then from-date (the one with none first). */
    public List<Rate> list(String sheet) {
        return jdbc.query("SELECT grade, pct, from_date, to_date FROM rate WHERE sheet = ? ORDER BY grade, from_key", ROW,
                sheet);
    }

    /** Sets the grade's rate from the from-date (through its to-date), replacing the one already there for that grade and from-date. */
    public void set(String sheet, RateInput input) {
        Date from = input.from() == null ? null : Date.valueOf(input.from());
        Date to = input.to() == null ? null : Date.valueOf(input.to());
        if (jdbc.update(
                "UPDATE rate SET pct = ?, to_date = ? WHERE sheet = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                input.pct(), to, sheet, input.grade(), from) == 0) {
            jdbc.update("INSERT INTO rate (sheet, grade, pct, from_date, to_date) VALUES (?, ?, ?, ?, ?)", sheet,
                    input.grade(), input.pct(), from, to);
        }
    }
}
package net.officefloor.hq.app.rate;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Responds with every grade's rate on the sheet. */
public class RespondWithRates {
    public void respond(@PathVariable("sheet") String sheet, Rates rates, ObjectResponse<List<Rate>> response) {
        response.send(rates.list(sheet));
    }
}
package net.officefloor.hq.app.rate;

import java.math.RoundingMode;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class SaveRate {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val RateInput input,
            Rates rates, Audit audit, Rollup rollup) {
        Rollup.Snapshot before = rollup.take(sheet);
        rates.set(sheet, input);
        audit.record("RATE_SET sheet=" + sheet + " by=" + user + " grade=" + input.grade() + " rate="
                + input.pct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + (input.from() == null ? "" : " from=" + input.from())
                + (input.to() == null ? "" : " to=" + input.to()));
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRate {
    private static final Set<String> GRADES = Set.of("A", "B", "C");
    private static final Pattern PCT = Pattern.compile("\\d{1,7}(\\.\\d{1,2})?");

    public void validate(@RequestBody RateRequest request, Out<RateInput> body) throws InvalidRateException {
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        String pct = request == null || request.pct() == null ? "" : request.pct().trim();
        String from = request == null || request.from() == null ? "" : request.from().trim();
        String to = request == null || request.to() == null ? "" : request.to().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidRateException("Grade must be A, B or C");
        }
        if (!PCT.matcher(pct).matches()) {
            throw new InvalidRateException("The rate must be a percent of 0.00 or more with up to two decimals");
        }
        LocalDate on;
        try {
            on = from.isEmpty() ? null : LocalDate.parse(from);
        } catch (DateTimeParseException e) {
            throw new InvalidRateException("Not a valid from-date: " + from);
        }
        LocalDate through;
        try {
            through = to.isEmpty() ? null : LocalDate.parse(to);
        } catch (DateTimeParseException e) {
            throw new InvalidRateException("Not a valid to-date: " + to);
        }
        if (on != null && through != null && through.isBefore(on)) {
            throw new InvalidRateException("The to-date must not be before the from-date");
        }
        body.set(new RateInput(grade, new BigDecimal(pct), on, through));
    }
}
