package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;

/**
 * A person on a sheet: name (unique on the sheet, ignoring case) and grades (A, B or C), each in force from its
 * from-date; grade is the one in force on the sheet's today. The version is raised by one on every save. The
 * retired-from date (yyyy-mm-dd) is null unless they are retired; once it is set they count as retired, whatever
 * the date. Their holds are listed in the order they were added; their OPEN claims dated within a hold, unless bound
 * by a statement, count in no live total. Their own terms (days) are null when they have none. retiredNow is whether
 * the sheet's today is on or after their retired-from date: from then their OPEN and PENDING claims, unless bound by a
 * statement, count in no live total.
 */
public record Person(long id, String name, String grade, long version, String retiredFrom, List<Hold> holds,
        List<GradeFrom> grades, Integer terms, boolean retiredNow) {

    /**
     * Whether the claim, theirs, counts toward the live totals: it counts, unless it is open, not bound by a statement,
     * and dated within one of their holds or their retirement date is reached.
     */
    public boolean counts(Claim claim) {
        if (!claim.counts()) {
            return false;
        }
        if (claim.status() == ClaimStatus.SETTLED || claim.bound()) {
            return true;
        }
        return !retiredNow && holds.stream().noneMatch((h) -> h.covers(claim.date()));
    }

    /** This person as they stand with the date for the sheet's today: their grade in force then, and retired then or not. */
    public Person on(LocalDate today) {
        return new Person(id, name, gradeOn(grades, today), version, retiredFrom, holds, grades, terms,
                retiredOn(retiredFrom, today));
    }

    /** Whether the sheet's today is on or after the retired-from date (null: never retired). */
    static boolean retiredOn(String retiredFrom, LocalDate today) {
        return retiredFrom != null && !today.isBefore(LocalDate.parse(retiredFrom));
    }

    /**
     * Whether the claim, theirs, counts toward a period ending on the date: by the status it had at the end of that
     * day (OPEN, PENDING or SETTLED; not yet added: no), unless deferred now, or open now, not bound by a statement
     * and dated within one of their holds or their retirement date is reached.
     */
    public boolean countsOn(Claim claim, LocalDate end) {
        ClaimStatus then = claim.statusOn(end);
        if (claim.deferred() || then == null) {
            return false;
        }
        if (then == ClaimStatus.SETTLED) {
            return true;
        }
        if (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING) {
            return false;
        }
        return (claim.status() != ClaimStatus.OPEN && claim.status() != ClaimStatus.PENDING) || claim.bound()
                || (!retiredNow && holds.stream().noneMatch((h) -> h.covers(claim.date())));
    }

    /** Whether a claim dated {@code date} is after this person's retirement, and so refused. */
    public boolean retiredBefore(LocalDate date) {
        return retiredFrom != null && date.isAfter(LocalDate.parse(retiredFrom));
    }

    /** The grade in force on the date: the one whose from-date is the latest on or before it (null when none). */
    public String gradeOn(LocalDate date) {
        return gradeOn(grades, date);
    }

    /**
     * Whether the claim has a figure apart from the grade in force on {@code today}: one it keeps (settled or
     * bound), one at another grade, in force on its date, or one from a rate that ended (its to-date) on or before
     * today, the claim not being dated after today. Their due-total is n/a only when no claim does and that grade
     * has no rate on today.
     */
    public boolean figureApartFrom(Claim claim, LocalDate today, List<Rate> rates, Dated floor) {
        String then = gradeOn(claim.date());
        return claim.fixed()
                || (then != null && !then.equals(gradeOn(today)) && claim.figure(rates, then, floor) != null)
                || (then != null && !LocalDate.parse(claim.date()).isAfter(today)
                        && claim.figure(rates, then, floor) != null);
    }

    /**
     * The due-by of a claim of theirs dated {@code date}, fixed when it is made: the terms-th business day after the
     * date (skipping weekends and the sheet's holidays as they stand now), the terms being the first of their own
     * terms, the terms of their grade then, and the sheet's terms then.
     */
    public LocalDate dueBy(String sheet, LocalDate date, Settings settings, Holidays holidays) {
        return holidays.businessDaysAfter(sheet, date, terms != null ? terms : settings.terms(sheet, gradeOn(date), date));
    }

    /** The grade in force on the claim's date (yyyy-mm-dd). */
    public String gradeOn(String date) {
        return gradeOn(LocalDate.parse(date));
    }

    static String gradeOn(List<GradeFrom> grades, LocalDate date) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && LocalDate.parse(g.from()).isAfter(date)) {
                continue;
            }
            if (found == null || (found.from() != null && g.from() != null && g.from().compareTo(found.from()) > 0)
                    || (found.from() == null && g.from() != null)) {
                found = g;
            }
        }
        return found == null ? null : found.grade();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.DatedValue;
import net.officefloor.hq.app.setting.Settings;

/**
 * What makes an overdue claim's late charge: the sheet's late percent (two decimals) by date, the one in force on each 30-day boundary after the claim's due-by, and its today; a claim is due
 * by the due-by fixed when it was added. The charge is never bound by a statement: it follows the sheet's today.
 * It also carries the sheet's policy date, which decides how a claim's live figures round, and each grade's grace
 * as recorded by from-date: the days a claim of a person whose grade in force on its date has a grace in force on
 * that date is given past its due-by before it is overdue.
 */
public record Late(Dated pct, LocalDate today, LocalDate policy, Map<String, List<DatedValue>> grace) {

    /**
     * How the claim's live figures round: half up when it rounds on a date (its own, or for a correction the date of
     * the claim it corrects) before the policy date, half to even on or after it.
     */
    public RoundingMode rounding(Claim claim) {
        return LocalDate.parse(claim.roundsOn()).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /**
     * The date the claim's overdue days are counted from: its due-by (fixed when it was added) plus the grace of the
     * grade (its person's in force on its date; null for none) in force on its date, if any.
     */
    public LocalDate graceBy(Claim claim, String grade) {
        LocalDate dueBy = LocalDate.parse(claim.dueBy());
        List<DatedValue> history = grade == null ? null : grace.get(grade);
        String days = history == null ? "" : Settings.on(history, LocalDate.parse(claim.date()));
        return days.isEmpty() ? dueBy : dueBy.plusDays(Integer.parseInt(days));
    }

    /** Whether the claim is overdue: OPEN or PENDING, not deferred, with its {@link #graceBy} before the sheet's today. */
    public boolean overdue(Claim claim, String grade) {
        return !claim.deferred() && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING) && graceBy(claim, grade).isBefore(today);
    }

    /**
     * The claim's late charge on its figure, compounding: for each full 30 days it is overdue, the late percent in force
     * on that boundary (its {@link #graceBy} plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries
     * before it, rounded in hundredths by the claim's {@link #rounding}, the charges added up (a boundary at 0.00 adds
     * nothing); 0.00 when it is not overdue, and always for a correction.
     */
    public BigDecimal charge(Claim claim, String grade, BigDecimal figure) {
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        if (figure == null || claim.correction() || !overdue(claim, grade)) {
            return total;
        }
        LocalDate dueBy = graceBy(claim, grade);
        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
        for (long k = 1; k <= periods; k++) {
            BigDecimal boundaryPct = pct.on(dueBy.plusDays(30 * k));
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { GRADES } from '../people/people';
import { useSheetToday } from '../sheet/sheet';
import type { Grade } from '../people/people';
import { rateOf, ratesKey, ratesPath, useRates } from './rates';
import type { Rate } from './rates';

type Draft = { grade: Grade; pct: string; from: string; to: string };
const EMPTY: Draft = { grade: 'A', pct: '', from: '', to: '' };

// The sheet's rates: each grade's rate in force on the sheet's today (n/a when none), every rate with its
// from-date (a blank from-date applies from the start) and to-date (a blank one has no end), and a form that sets one, replacing the rate already
// there for that grade and from-date.
function Rates({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const [draft, setDraft] = useState<Draft>(EMPTY);

  const save = useMutation({
    mutationFn: (body: Draft) => postJson<Rate[]>(byUser(ratesPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(ratesKey(sheet), updated);
      setDraft((d) => ({ ...d, pct: '', from: '', to: '' }));
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a percent that is not 0.00 or more with up to two decimals, a bad from- or to-date, or a to-date before the from-date.
    send(draft);
  };

  return (
